CREATE OR REPLACE FUNCTION public.validate_criterion_official_label() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.owner_id IS NULL AND NOT NEW.is_placeholder AND NOT EXISTS(SELECT 1 FROM public.criteria_versions v WHERE v.id=NEW.criteria_version_id AND v.is_official AND length(trim(coalesce(v.source_reference,'')))>0) THEN RAISE EXCEPTION 'Official criterion requires verified version source' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.validate_criterion_official_label() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER standards_validate_official_label BEFORE INSERT OR UPDATE OF is_placeholder,criteria_version_id ON public.standards FOR EACH ROW EXECUTE FUNCTION public.validate_criterion_official_label();